function search(){return`<h1>🔎 খুঁজুন</h1><p class="note">জেলা, বিভাগ, অঞ্চল, খাবার বা স্থান লিখুন — যেমন “দই”, “মহাস্থানগড়”</p><input id="q" placeholder="খুঁজুন…" value="${window.lastQ||''}" oninput="doSearch(this.value)"><div id="smap">${mapHTML(null)}</div><div id="res"></div>${FT}`}
const N=t=>String(t).toLowerCase().replace(/\u09DF/g,'\u09AF\u09BC').replace(/\u09DC/g,'\u09A1\u09BC').replace(/\u09DD/g,'\u09A2\u09BC').replace(/ঙ্গ/g,'ংগ').replace(/ণ/g,'ন').replace(/ী/g,'ি').replace(/ঈ/g,'ই').replace(/ূ/g,'ু').replace(/ঊ/g,'উ');
function doSearch(v){window.lastQ=v;v=v.trim().toLowerCase();if(!v){$('#res').innerHTML='';$('#smap').innerHTML=mapHTML(null);window.lastSec=0;return}
 var sm=v.match(/^(?:সেক্টর|sector)\s*([০-৯0-9]{1,2})$/);if(sm){var sn=parseInt(sm[1].replace(/[০-৯]/g,function(d){return '০১২৩৪৫৬৭৮৯'.indexOf(d)}));if(sn>=1&&sn<=SEC.length){if(window.lastSec!=sn){_sw=1;window.lastSec=sn}var SD=SEC[sn-1].d.map(function(e){return DB.find(function(x){return x.en==e})}).filter(Boolean);$('#smap').innerHTML=mapHTML(null,sn);$('#res').innerHTML=secInfo(sn)+SD.map(function(d){return '<div class="row" onclick="show(\''+d.en.replace("'","\\'")+'\')"><span>'+E(d.bn)+' <small style="color:var(--mut)">'+E(DIV[d.dv])+'</small></span></div>'}).join('');return}}window.lastSec=0;
 const hit=DB.filter(d=>{const i=INFO[d.en]||{};return N([d.bn,d.en,DIV[d.dv],REG[d.rg][0],...(i.f||[]),...(i.p||[]),...(i.pr||[]),...(i.pe||[]),...(i.up||[]),...secOf(d.en).map(s=>'সেক্টর '+bdn(s.n)+' sector '+s.n)].join(' ')).includes(N(v))});
 $('#smap').innerHTML=mapHTML(hit);$('#res').innerHTML=hit.map(d=>`<div class="row" onclick="show('${d.en.replace("'","\\'")}')"><span><b>${d.bn}</b> → ${DIV[d.dv]} বিভাগ → ${REG[d.rg][0]}<br><small style="color:var(--mut)">${[...((INFO[d.en]||{}).f||[]),...((INFO[d.en]||{}).p||[])].join(' · ')}</small></span></div>`).join('')||'<p class="note">কিছু পাওয়া যায়নি (তথ্যভান্ডার বাড়ছে)</p>'}
