async function qaSend(path,body,msgId,btn,okm){let last=0;try{last=+localStorage.getItem('qaLast')||0}catch(e){}
 if(Date.now()-last<20000){$(msgId).textContent='একটু অপেক্ষা করে আবার পাঠান';return}
 if(btn){btn.disabled=true;btn.dataset.t=btn.textContent;btn.textContent='⏳ পাঠানো হচ্ছে…'}
 try{const r=await fetch(QA+path,{method:'POST',body:JSON.stringify({...body,ts:Date.now()})});if(!r.ok)throw 0;try{localStorage.setItem('qaLast',Date.now())}catch(e){}qaData=null;qaErr='';qaNote=okm;render();scrollTo(0,0)}catch(e){if(btn){btn.disabled=false;btn.textContent=btn.dataset.t}$(msgId).textContent='পাঠানো যায়নি, আবার চেষ্টা করুন'}}
