function mergeCust(c){if(!c||typeof c!='object')return;['g','g2','r'].forEach(function(k){if(HEXR.test(c[k]||''))CUST[k]=c[k]});if(typeof c.anim=='boolean')CUST.anim=c.anim;if(typeof c.fx=='boolean')CUST.fx=c.fx;if(typeof c.sb=='boolean')CUST.sb=c.sb;if(['none','fade','slide','pop'].indexOf(c.ca)>=0)CUST.ca=c.ca;if(['burst','ring','none'].indexOf(c.fb)>=0)CUST.fb=c.fb;if(c.blocks&&typeof c.blocks=='object')['progress','fav','sector','law','about','theme'].forEach(function(k){if(typeof c.blocks[k]=='boolean')CUST.blocks[k]=c.blocks[k]});if(Array.isArray(c.lbox))CUST.lbox=c.lbox.slice(0,40).map(cleanLb);if(typeof c.lt=='string')CUST.lt=c.lt.slice(0,80);if(typeof c.ls=='string')CUST.ls=c.ls.slice(0,100);if(Array.isArray(c.mbox))CUST.mbox=c.mbox.slice(0,30).map(function(b){b=b||{};return{ic:String(b.ic||'').slice(0,4),t:String(b.t||'').slice(0,80),v:String(b.v||'').slice(0,2000),l:String(b.l||'').slice(0,40),u:/^https:\/\//.test(b.u||'')?String(b.u).slice(0,300):'',c:HEXR.test(b.c||'')?b.c:'#1f6fd1',an:ANS.some(function(a){return a[0]==b.an})?b.an:'none',top:!!b.top}})}
function collectCust(){var g=function(i){return document.getElementById(i)};if(g('cu_g')){['g','g2','r'].forEach(function(k){var v=g('cu_'+k).value;if(HEXR.test(v))CUST[k]=v});CUST.anim=g('cu_anim').checked;CUST.fx=g('cu_fx').checked;CUST.sb=g('cu_sb').checked;CUST.ca=g('cu_ca').value;CUST.fb=g('cu_fb').value;['progress','fav','sector','law','about','theme'].forEach(function(k){CUST.blocks[k]=g('bk_'+k).checked});var m=[];for(var j=0;g('mb_t_'+j);j++)m.push({ic:g('mb_i_'+j).value.slice(0,4),t:g('mb_t_'+j).value.trim().slice(0,80),v:g('mb_v_'+j).value.trim().slice(0,2000),l:g('mb_l_'+j).value.trim().slice(0,40),u:/^https:\/\//.test(g('mb_u_'+j).value.trim())?g('mb_u_'+j).value.trim().slice(0,300):'',c:HEXR.test(g('mb_c_'+j).value)?g('mb_c_'+j).value:'#1f6fd1',an:g('mb_a_'+j).value,top:g('mb_p_'+j).checked});CUST.mbox=m}}
