async function chCode(){const a=$('#c0').value,b=$('#c1').value,c=$('#c2').value;try{if(await sha(a)!=curHash)msg='❌ বর্তমান কোড ভুল';else if(b.length<6)msg='❌ নতুন কোড কমপক্ষে ৬ অক্ষরের দিন (৮+ ভালো)';else if(b!=c)msg='❌ নতুন কোড দুটি মেলেনি';else{curHash=await sha(b);try{localStorage.setItem('bdHash',curHash)}catch(e){}msg='✅ কোড বদলেছে (এই ব্রাউজারে)। সব ডিভাইসে কার্যকর করতে নিচে এক্সপোর্ট করে data.json GitHub-এ আপলোড করুন।'}}catch(e){msg='❌ কোড বদলানো যায়নি (HTTPS লাগবে)'}render()}
function restoreDef(){var n=0;DEF.forEach(function(d){if(!DB.find(function(x){return x.en==d.en})){var c=Object.assign({},d);while(DB.find(function(z){return z.x==c.x&&z.y==c.y}))c.y++;DB.push(c);if(!INFO[d.en])INFO[d.en]=JSON.parse(JSON.stringify(INFO0[d.en]||{}));n++}});fillUp();persist();msg=n?'✅ '+n+'টি হারানো জেলা ফিরিয়ে আনা হয়েছে':'সব '+DEF.length+' জেলা আগে থেকেই আছে';render()}
function rst(){try{localStorage.removeItem('bdData')}catch(e){}msg='রিসেট হয়েছে — পেজ রিলোড করুন';render()}
const opts=(o,v)=>Object.entries(o).map(([k,n])=>`<option value="${k}" ${k==v?'selected':''}>${Array.isArray(n)?n[0]:n}</option>`).join('');

var LB={f:'🍛 বিখ্যাত খাবার',p:'🏞️ দর্শনীয় স্থান',pr:'🌾 বিখ্যাত পণ্য',pe:'👤 বিখ্যাত মানুষ',up:'🏘️ উপজেলা / থানা'};
function lst(k,i){var a=i[k]||[];return '<div class="card" style="margin:8px 0"><b>'+LB[k]+'</b> <button class="chip" onclick="clrBox(\''+k+'\')">🗑️ বক্স খালি করুন</button><div style="margin-top:4px">'+(a.map(function(x,j){return '<span class="chip">'+E(x)+' <b onclick="delItem(\''+k+'\','+j+')" style="color:var(--r);cursor:pointer;padding:2px 6px">✕</b></span>'}).join('')||'<small style="color:var(--mut)">খালি — দর্শকদের কাছে এই বক্স দেখাবে না</small>')+'</div><div style="display:flex;gap:6px;margin-top:6px"><input id="ai_'+k+'" placeholder="নতুন যোগ করুন"><button class="opt" style="width:auto;margin:0;padding:10px 16px" onclick="addItem(\''+k+'\')">➕</button></div></div>'}
function editorV(d,i){var cx=i.cx||[];return '<div class="card" style="margin:10px 0"><b>'+E(d.bn)+'</b><label>বাংলা নাম</label><input id="e_bn" value="'+E(d.bn)+'"><label>বিভাগ</label><select id="e_dv">'+opts(DIV,d.dv)+'</select><label>বঙ্গ-অঞ্চল</label><select id="e_rg">'+opts(REG,d.rg)+'</select></div>'
 +['f','p','pr','pe','up'].map(function(k){return lst(k,i)}).join('')
 +'<div class="card" style="margin:8px 0"><b>🏛️ ইউনিয়ন / পৌরসভা / গ্রাম</b> <button class="chip" onclick="clrBox(\'st\')">🗑️ খালি করুন</button><label>ইউনিয়ন পরিষদ সংখ্যা</label><input id="e_un" value="'+E(i.un||'')+'"><label>পৌরসভা সংখ্যা</label><input id="e_pz" value="'+E(i.pz||'')+'"><label>গ্রাম সংখ্যা</label><input id="e_vl" value="'+E(i.vl||'')+'"></div>'
 +[['h','📜 ইতিহাস'],['w','🇧🇩 মুক্তিযুদ্ধ']].map(function(a){return '<div class="card" style="margin:8px 0"><b>'+a[1]+'</b> <button class="chip" onclick="clrBox(\''+a[0]+'\')">🗑️ মুছুন</button><textarea id="e_'+a[0]+'" rows="3">'+E(i[a[0]]||'')+'</textarea></div>'}).join('')
 +cx.map(function(b,j){return '<div class="card" style="margin:8px 0"><b>📌 নিজের বক্স</b> <button class="chip" onclick="rmCx('+j+')">🗑️ এই বক্স মুছুন</button><input id="cxt_'+j+'" value="'+E(b.t||'')+'" placeholder="বক্সের শিরোনাম"><label></label><textarea id="cxv_'+j+'" rows="3" placeholder="লেখা">'+E(b.v||'')+'</textarea></div>'}).join('')
 +'<button class="opt" onclick="addCx()">➕ নতুন বক্স যোগ করুন</button>'
 +'<label>ম্যাপে অবস্থান সরান (দখল থাকলে অদলবদল হবে)</label><div class="seg"><button onclick="mv(-1,0)">◀</button><button onclick="mv(0,-1)">▲</button><button onclick="mv(0,1)">▼</button><button onclick="mv(1,0)">▶</button></div><div class="seg"><button class="on" onclick="sv()">💾 সেভ</button></div>'
 +'<details '+(dq?'open':'')+' class="card" style="margin:10px 0"><summary style="color:var(--r)">⚠️ বিপজ্জনক অংশ</summary><small style="color:var(--mut)">এটি চাপলে পুরো জেলাটাই (নাম ও ম্যাপের ঘরসহ) মুছে যায়। শুধু কোনো বক্স বা তথ্য মুছতে চাইলে উপরের ✕ / "মুছুন" ব্যবহার করুন।</small><div class="seg"><button onclick="rm()">'+(dq?'⚠️ '+E(d.bn)+' মুছবেন? আবার চাপুন':'🗑️ পুরো জেলা মুছুন')+'</button></div></details>'+mapHTML([d])}
function cur(){return INFO[ed]=INFO[ed]||{}}
function delItem(k,j){sv(1);var o=cur();if(k=='up')o.upe=1;if(o[k])o[k].splice(j,1);persist();msg='🗑️ আইটেম মুছে ফেলা হয়েছে';render()}
