function clrBox(k){sv(1);var o=cur();if(k=='up')o.upe=1;if(k=='st'){o.un=o.pz=o.vl='';o.ste=1}else o[k]=(k=='h'||k=='w')?'':[];persist();msg='🗑️ বক্স খালি করা হয়েছে';render()}
function addCx(){sv(1);var o=cur();(o.cx=o.cx||[]).push({t:'',v:''});persist();msg='➕ নতুন বক্স যোগ হয়েছে — শিরোনাম ও লেখা দিয়ে "সেভ" চাপুন';render()}
function rmCx(j){sv(1);var o=cur();if(o.cx)o.cx.splice(j,1);persist();msg='🗑️ বক্স মুছে ফেলা হয়েছে';render()}
function adminV(){if(!admin)return'<p class="note">আগে "আরও" থেকে কোড দিয়ে প্রবেশ করুন</p>';const d=DB.find(x=>x.en==ed),i=d?INFO[d.en]||{}:{},T=(id,t,a)=>`<label>${t}</label><textarea id="${id}" rows="3">${E((a||[]).join('\n'))}</textarea>`;
 return`<h1>🔐 অ্যাডমিন প্যানেল</h1><div class="note">${msg||'পরিবর্তন শুধু এই ব্রাউজারে সেভ হয়। সবার জন্য স্থায়ী করতে নিচে "এক্সপোর্ট" করে data.json নামে GitHub-এ আপলোড করুন।'}</div>
 <h2>✏️ জেলা সম্পাদনা</h2><select onchange="ed=this.value;dq=false;msg='';render()"><option value="">জেলা বাছুন…</option>${DB.map(x=>`<option value="${E(x.en)}" ${x.en==ed?'selected':''}>${E(x.bn)} (${E(x.en)})</option>`).join('')}</select>
 ${d?editorV(d,i):''}
 <h2>➕ নতুন জেলা</h2><div class="card"><input id="n_bn" placeholder="বাংলা নাম"><label></label><input id="n_en" placeholder="English name (unique)"><label>বিভাগ</label><select id="n_dv">${opts(DIV)}</select><label>অঞ্চল</label><select id="n_rg">${opts(REG)}</select><button class="opt" onclick="add()">যোগ করুন</button></div>
 ${custV()}${lawAdmin()}<h2>⚙️ সাইট সেটিং</h2><div class="card"><label>অ্যাপের শিরোনাম</label><input id="c_title" value="${E(CFG.title)}"><label>উপশিরোনাম</label><input id="c_sub" value="${E(CFG.sub)}"><label>ডেভেলপারের নাম (ক্রেডিট)</label><input id="c_dev" value="${E(CFG.dev)}"><label>Telegram ইউজারনেম (@ ছাড়া)</label><input id="c_tg" value="${E(CFG.tg)}"><label>Facebook প্রোফাইল লিংক</label><input id="c_fb" value="${E(CFG.fb)}"><button class="opt" onclick="saveCfg()">💾 সেভ</button></div>
 <h2>🎨 বিভাগ ও অঞ্চলের নাম / রঙ</h2><div class="card">${Object.keys(DIV).map(k=>`<div style="display:flex;gap:8px;margin:6px 0"><input id="dn_${k}" value="${E(DIV[k])}"><input id="dc_${k}" type="color" value="${DC[k]}" style="width:56px;padding:2px"></div>`).join('')}<small style="color:var(--mut)">বঙ্গ-অঞ্চল:</small>${Object.keys(REG).map(k=>`<div style="display:flex;gap:8px;margin:6px 0"><input id="rn_${k}" value="${E(REG[k][0])}"><input id="rc_${k}" type="color" value="${REG[k][1]}" style="width:56px;padding:2px"></div>`).join('')}<button class="opt" onclick="saveColors()">💾 সেভ</button></div>
 <h2>📝 নিজের কুইজ প্রশ্ন</h2><div class="card"><textarea id="qz" rows="5" placeholder="প্রশ্ন | সঠিক উত্তর | ভুল১ | ভুল২ | ভুল৩">${E(QZ.map(q=>[q[0],q[1],...q[2]].join(' | ')).join('\n'))}</textarea><small style="color:var(--mut)">প্রতি লাইনে একটি প্রশ্ন। কুইজে এগুলো সবসময় আসবে।</small><button class="opt" onclick="saveQZ()">💾 সেভ</button></div>
 <h2>👤 আমার সম্পর্কে (সবাই দেখবে)</h2><div class="card"><textarea id="ab" rows="6" maxlength="2000" placeholder="নিজের সম্পর্কে যা ইচ্ছা লিখুন…">${E(ABOUT)}</textarea><small style="color:var(--mut)">ফোন নম্বর, ঠিকানা বা ব্যক্তিগত গোপন তথ্য দেবেন না — সাইটে সবাই দেখতে পাবে।</small><button class="opt" onclick="saveAbout()">💾 সেভ</button></div>
 <h2>🏘️ উপজেলা বাল্ক ইমপোর্ট</h2><div class="card"><textarea id="bu" rows="6" placeholder="প্রতি লাইনে একটি জেলা:
বগুড়া: বগুড়া সদর, আদমদীঘি, ধুনট | ইউনিয়ন: ১০৯ | পৌরসভা: ৯ | গ্রাম: ১৮৫৭"></textarea><small style="color:var(--mut)">সরকারি তালিকা (যেমন bangladesh.gov.bd) থেকে দেখে পেস্ট করুন। "| ইউনিয়ন/পৌরসভা/গ্রাম" অংশ ঐচ্ছিক।</small><button class="opt" onclick="bulkUp()">⬇️ যোগ করুন</button></div>
 <h2>❓ প্রশ্নোত্তর সেটআপ</h2><div class="card"><input id="qu" value="${E(QA)}" placeholder="https://আপনার-প্রজেক্ট-default-rtdb.firebaseio.com"><small style="color:var(--mut)">Firebase Realtime Database-এর URL। ফাঁকা রাখলে প্রশ্নোত্তর বন্ধ থাকবে।</small><button class="opt" onclick="saveQA()">💾 সেভ</button></div>
 <h2>🔑 অ্যাডমিন কোড পরিবর্তন</h2><div class="card"><input id="c0" type="password" placeholder="বর্তমান কোড"><label></label><input id="c1" type="password" placeholder="নতুন কোড (৬+ অক্ষর)"><label></label><input id="c2" type="password" placeholder="নতুন কোড আবার লিখুন"><button class="opt" onclick="chCode()">কোড বদলান</button></div>
 <h2>🚀 সবার জন্য প্রকাশ করুন</h2><div class="card"><small style="color:var(--mut)">বদলগুলো এখন শুধু আপনার ব্রাউজারে আছে। সবার ফোনে দেখাতে নিচের বাটনে ডেটাসহ নতুন index.html নামিয়ে GitHub-এ পুরোনোটার জায়গায় আপলোড করুন — আলাদা data.json লাগবে না।</small><button class="opt" onclick="dlSite()">⬇️ ডেটাসহ index.html ডাউনলোড</button><button class="opt" onclick="djCheck()">🔍 সবার জন্য কী দেখাচ্ছে — পরীক্ষা</button><div id="djr" class="note" style="margin-top:8px">পরীক্ষার ফল এখানে আসবে।</div></div>
 <h2>💾 ডেটা এক্সপোর্ট / ইমপোর্ট (পুরোনো উপায়: data.json)</h2><div class="card"><textarea id="js" rows="6" placeholder="এখানে JSON আসবে / পেস্ট করুন"></textarea><div class="seg"><button onclick="expo()">এক্সপোর্ট</button><button onclick="impo()">ইমপোর্ট</button><button onclick="rst()">রিসেট</button><button onclick="restoreDef()">↩️ হারানো জেলা ফেরান</button><button onclick="applyOffBtn()">📥 সরবরাহকৃত তালিকা ফেরান</button></div></div>
 <div class="seg"><button onclick="admin=false;msg='';go('more')">🔒 লগআউট</button></div>${FT}`}
var SRC='ডিফল্ট (অ্যাপের ভেতরের ডেটা)',DJERR='';
function djUrl(h){var u=(h||location.href).split('#')[0].split('?')[0];if(!/\/$/.test(u)&&!/\/[^\/]*\.[^\/]*$/.test(u))u+='/';return u.replace(/[^\/]*$/,'')+'data.json'}
(function(){var ok=0;mkFT();applyTheme();
 try{var v=localStorage.getItem('bdData');if(v){apply(JSON.parse(v));ok=1;SRC='এই ব্রাউজারে সেভ-করা (লোকাল)'}}catch(e){try{localStorage.removeItem('bdData')}catch(_){}}
 if(!ok){try{var sd=document.getElementById('seed');if(sd&&sd.textContent.trim()){apply(JSON.parse(sd.textContent));ok=2;SRC='index.html-এ এমবেড করা ডেটা'}}catch(e){DJERR='এমবেড ডেটা: '+e.message}}
 fillUp();render();
 if(ok<1&&window.fetch){fetch(djUrl(),{cache:'no-cache'}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}).then(function(o){apply(o);SRC='data.json';try{if(HX.test(o.hash||'')&&!localStorage.getItem('bdHash'))curHash=o.hash}catch(e){}render()}).catch(function(e){DJERR='data.json: '+e.message})}})();

/* ===== water & galaxy FX (script) ===== */
var FXW=0,FXC=null,fxy=0,fxr=0;
function FXOFF(){var c=document.documentElement.classList;return c.contains('noanim')||c.contains('nofx')||(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches)}
function fxTheme(){var d=document.documentElement.dataset.theme,dk=d=='dark'||(d!='light'&&window.matchMedia&&matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.classList.toggle('fxd',dk)}
(function(){var b=document.createElement('div');b.id='fxbg';var h='<div class="pg pg1"><i class="fxl l1"></i><i class="fxl l2"></i><i class="fxs s1"></i></div><div class="pg pg2"><i class="fxw w1"></i><i class="fxw w2"></i></div><div class="pg pg3"><i class="fxl l3"></i><i class="fxs s2"></i>';for(var i=0;i<6;i++){var z=10+(i*7)%22;h+='<i class="fxb" style="left:'+(8+(i*53)%84)+'%;width:'+z+'px;height:'+z+'px;--bx:'+((i%2?1:-1)*(12+i*4))+'px;animation-duration:'+(15+(i*5)%13)+'s;animation-delay:-'+((i*4)%14)+'s"></i>'}h+='</div>';b.innerHTML=h;document.body.insertBefore(b,document.body.firstChild);var r=document.createElement('div');r.id='fxrip';document.body.appendChild(r);fxTheme();try{new MutationObserver(fxTheme).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});var mq=matchMedia('(prefers-color-scheme:dark)');mq.addEventListener?mq.addEventListener('change',fxTheme):mq.addListener(fxTheme)}catch(e){}})();
var fxP=null,fxLT=0,fxSlow=0,fxSt=0;
document.addEventListener('scroll',function(e){var t=e.target;fxy=(t&&t!==document&&t.scrollTop!=null)?t.scrollTop:(window.pageYOffset||0);var c=document.documentElement.classList;if(!c.contains('scrolling'))c.add('scrolling');clearTimeout(fxSt);fxSt=setTimeout(function(){c.remove('scrolling');fxLT=0},160);if(!fxr){fxr=1;requestAnimationFrame(function(ts){fxr=0;if(!fxP)fxP=document.querySelectorAll('#fxbg .pg');if(fxP.length===3){var y=-fxy;fxP[0].style.transform='translate3d(0,'+(y*.06).toFixed(1)+'px,0)';fxP[1].style.transform='translate3d(0,'+(y*.05).toFixed(1)+'px,0)';fxP[2].style.transform='translate3d(0,'+(y*.12).toFixed(1)+'px,0)'}if(fxLT&&ts-fxLT>46&&ts-fxLT<180){if(++fxSlow>=8)c.add('fxlite')}fxLT=ts})}},true);
function fxRipAt(x,y){if(FXOFF())return;var h=document.getElementById('fxrip');if(!h||h.children.length>14)return;var a=document.createElement('span');a.className='rip';a.style.left=x+'px';a.style.top=y+'px';var c=a.cloneNode();c.className='rip r2';h.appendChild(a);h.appendChild(c);setTimeout(function(){a.remove();c.remove()},1250)}
